@push('scripts')<script>
$(function(){

 const table=$('#equipmentIssueTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.equipment-issues.dt')),data:d=>{d.from_date=$('#issueFrom').val();d.to_date=$('#issueTo').val()}},columns:[{data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false},{data:'number',name:'number'},{data:'date_label',name:'issue_date'},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'unit',orderable:false,searchable:false},{data:'quantity',orderable:false,searchable:false},{data:'description',orderable:false,searchable:false}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 $('#showIssue').on('click',()=>table.ajax.reload());$('#issueFrom,#issueTo').on('change',()=>table.ajax.reload());
 $('#exportIssue').on('click',function(e){e.preventDefault();location.href=this.href+'?'+$.param({from_date:$('#issueFrom').val(),to_date:$('#issueTo').val()})});
 $(document).on('click','.btn-delete-equipment-issue',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.equipment-issues.destroy',['equipmentIssue'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}))})});
});
</script>@endpush
